{
  "products": [
    {
      "name": "Pokémon (Scarlet & Violet, Legends: Arceus)",
      "line": "Pokémon hands your child a huge world to roam, creatures to collect, and a goal that unfolds at their own pace. Scarlet and Violet drop them into an open region they can explore in any order. Legends: Arceus is the calmer of the two, leaning more into discovery than battling. Both carry an E for Everyone rating.",
      "requires_original_platform": false
    },
    {
      "name": "Stardew Valley",
      "line": "Stardew Valley is a gentle farming game. There's no clock, no enemies you're forced to fight, and no way to actually lose. Your child plants crops, befriends the townspeople, and builds a farm at whatever pace feels right to them. It costs about $15 once and runs on nearly every device you own.",
      "requires_original_platform": false
    },
    {
      "name": "Animal Crossing: New Horizons",
      "line": "Animal Crossing gives your child a whole island to shape, with decorating, fishing, and visits to friendly animal neighbors. It moves in real time and never rushes anyone, which makes it one of the gentlest games on this whole list. It's a Switch game, rated E for Everyone, and usually runs around $55.",
      "requires_original_platform": false
    },
    {
      "name": "Canva (and Canva for Education), for design",
      "line": "Canva turns your child into a designer using drag-and-drop tools that feel a lot like play. They can put together posters, cards, comic strips, and slideshows in minutes, then print or share whatever they made. The core app is free, and Canva for Education is completely free for K-12 teachers and students.",
      "requires_original_platform": false
    },
    {
      "name": "Procreate and Procreate Dreams, for drawing and animation",
      "line": "Procreate is a professional-grade drawing app, yet it's still simple enough for a kid to open and start sketching right away. Its companion app, Procreate Dreams, lets them turn those drawings into animation. Procreate is a one-time $12.99 purchase with no subscription attached, which is a rarity worth celebrating.",
      "requires_original_platform": false
    },
    {
      "name": "FL Studio, for music-making",
      "line": "FL Studio is a full music-production studio, the real software working musicians use to build beats and songs. This is the pick for the kid who's serious about making music, not the one looking for a casual ten-minute play. Pricing starts at $99 as a one-time purchase, and the updates are free for life.",
      "requires_original_platform": false
    },
    {
      "name": "Toca Boca World",
      "line": "Toca Boca World is an open-ended digital playset. Kids invent stories, characters, and scenes, with no goals and nothing to win. It's rated 4+ and free to download.",
      "requires_original_platform": false
    },
    {
      "name": "LEGO Builder's Journey",
      "line": "LEGO Builder's Journey is a quiet, beautiful puzzle game about building with LEGO bricks, and the tone stays calm throughout. It's a one-time $19.99 purchase, rated E (3+).",
      "requires_original_platform": false
    },
    {
      "name": "Taroo",
      "line": "Taroo blends open-ended play with real creative tools, so you get the appeal of Roblox without the open chat with strangers. It's built to be an entertainment space and a maker tool at once, in one place that's safe by design. Most apps leave your child to either watch or play. Taroo has them make.",
      "requires_original_platform": false
    }
  ]
}
